@sig trait DoctorRequestQualification_Api {
  def id: Art.BridgeId
  def doctor_signal_Id : Art.PortId
  def request_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var request_facts: EIT_Acquisition_Supervisor.RequestFactsRecord = $

  def put_request_facts(value : EIT_Acquisition_Supervisor.RequestFactsRecord) : Unit = {
    Contract(
      Modifies(request_facts),
      Ensures(
        request_facts == value
      )
    )
    Spec {
      request_facts = value
    }

    Art.putValue(request_facts_Id, EIT_Acquisition_Supervisor.RequestFactsRecord_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DoctorRequestQualification_Initialization_Api (
  val id: Art.BridgeId,
  val doctor_signal_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends DoctorRequestQualification_Api

@datatype class DoctorRequestQualification_Operational_Api (
  val id: Art.BridgeId,
  val doctor_signal_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends DoctorRequestQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var doctor_signal: EIT_Acquisition_Supervisor.DoctorSignal.Type = $

  def get_doctor_signal() : Option[EIT_Acquisition_Supervisor.DoctorSignal.Type] = {
    Contract(
      Ensures(
        Res == Some(doctor_signal)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.DoctorSignal.Type] = Art.getValue(doctor_signal_Id) match {
      case Some(EIT_Acquisition_Supervisor.DoctorSignal_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port doctor_signal.  Expecting 'EIT_Acquisition_Supervisor.DoctorSignal_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.DoctorSignal.Type]()
      case _ => None[EIT_Acquisition_Supervisor.DoctorSignal.Type]()
    }
    return value
  }
}
